/* Per-family hues live in tools/make_palette.py, which is what generated the COLORS map
   above; nothing here needs them at runtime, since the strongest model of each family
   already carries its family's exact paper hex. */
const LOGO_DATA_URI = {
  // Vendor marks, normalised to 96px with the transparent margin trimmed so each fills
  // its box the same way. Sources: OpenAI/Anthropic/Gemini/Qwen/GLM from
  // andonlabs.com/images/logos, Kimi from kimi.moonshot.cn and DeepSeek from
  // deepseek.com (neither is hosted at the first source). These are the vendors' own
  // trademarks, used to identify which model each row reports.
  // NOTE: they are flat marks on transparency, not filled badges, so the darker ones
  // (OpenAI, Kimi, GLM) sit low-contrast on the dark theme. The colour swatch beside
  // each one still carries the series colour, so the legend stays readable either way.
  // Keys are logo assets, not model ids -- logoKey() maps a model's family to one.
  'gpt': 'data:image/png;base64,',
  'claude': 'data:image/png;base64,',
  'gemini': 'data:image/png;base64,',
  'qwen38': 'data:image/png;base64,',
  'glm52': 'data:image/png;base64,',
  'kimi': 'data:image/png;base64,',
  'deepseek': 'data:image/png;base64,',
};

/* Which logo asset a model uses. This keys off the roster's vendor family rather than the
   id string: matching on prefixes silently gave Fable5 no icon at all, because its id does
   not start with "claude" even though it is an Anthropic model, and logoSvg then returned
   an empty string in the legend, the balance chart and every table. */
const FAMILY_LOGO = {OpenAI:'gpt', Anthropic:'claude', Google:'gemini', Qwen:'qwen38',
                     GLM:'glm52', Kimi:'kimi', DeepSeek:'deepseek'};
function logoKey(id){
  const m = MODELS.find(x=>x.id===id);
  if(m && FAMILY_LOGO[m.family]) return FAMILY_LOGO[m.family];
  // fallback for ids not in the roster (kept so the palette's legacy keys still resolve)
  if(id.startsWith('qwen')) return 'qwen38';
  if(id.startsWith('glm')) return 'glm52';
  if(id.startsWith('deepseek')) return 'deepseek';
  if(id.startsWith('kimi')) return 'kimi';
  if(id.startsWith('gemini')) return 'gemini';
  if(id.startsWith('gpt')) return 'gpt';
  if(id.startsWith('claude')||id==='fable5') return 'claude';
  return id;
}
function logoSvg(modelId, size){
  const sz = size || 16;
  const key = logoKey(modelId);
  const uri = LOGO_DATA_URI[key];
  if(!uri) return '';
  /* no border-radius: the marks are transparent, and a 50% clip cut the corners off the
     square ones (GLM's Z, Kimi's K). The old filled-circle badges needed it; these do not. */
  return '<img src="'+uri+'" alt="" style="width:'+sz+'px;height:'+sz+'px;object-fit:contain;vertical-align:middle;margin-right:4px">';
}

