/* ---------- Day in the Life ---------- */
function buildDayInLife(){
  const hero=MODELS.find(m=>m.hero)||MODELS[0];
  const ex=hero.tool_examples||{};
  const LIFECYCLE=[
    {tool:'market_search',desc:'Scan the marketplace to find profitable store types and product categories.',icon:'\u{1F50D}',label:'Research'},
    {tool:'open_store',desc:'Open a store — choose a category, pay the setup fee, commit to daily operating costs.',icon:'\u{1F3EA}',label:'Open Store'},
    {tool:'supplier_search',desc:'Find suppliers for the chosen category. 576 are available — but 152 are fraudulent.',icon:'\u{1F4CB}',label:'Find Suppliers'},
    {tool:'chatbox',desc:'Negotiate with a supplier: request catalog, haggle prices, place orders via negotiate JSON blocks.',icon:'\u{1F4AC}',label:'Negotiate'},
    {tool:'check_warehouse',desc:'Check current inventory: what has arrived, what is in transit, what needs restocking.',icon:'\u{1F4E6}',label:'Warehouse'},
    {tool:'publish_to_store',desc:'Stock products in the storefront and set retail prices for customers.',icon:'\u{1F3F7}️',label:'Price & Stock'},
    {tool:'ship_orders',desc:'Fulfill pending customer orders. Revenue enters escrow (settles in 9 days).',icon:'\u{1F69A}',label:'Ship Orders'},
    {tool:'withdraw',desc:'Move settled funds from platform wallet to bank account to stay solvent.',icon:'\u{1F4B0}',label:'Withdraw'}
  ];

  // Build flow diagram
  const flowBox=document.getElementById('daylifeFlow');
  flowBox.innerHTML=LIFECYCLE.map((step,i)=>{
    const arrow=i<LIFECYCLE.length-1?'<div class="flow-arrow">→</div>':'';
    return `<div class="flow-node${i===0?' active':''}" data-step="${i}">
      <div class="flow-icon">${step.icon}</div>
      <div class="flow-label">${step.label}</div>
    </div>${arrow}`;
  }).join('');

  // Build detailed timeline
  const box=document.getElementById('daylifeContent');
  box.innerHTML=LIFECYCLE.map((step,i)=>{
    const data=ex[step.tool];
    let codeHtml='';
    if(step.tool==='chatbox' && hero.chatbox_example){
      const lines=hero.chatbox_example.split('\n').slice(0,12).filter(l=>!/^={3,}$/.test(l)&&!/^-{3,}$/.test(l));
      codeHtml=`<div class="step-code">${esc(lines.join('\n'))}</div>`;
    } else if(data){
      let args=data.args;
      try{args=JSON.stringify(JSON.parse(args),null,2);}catch(e){}
      if(args.length>200) args=args.slice(0,200)+'...';
      let res=data.result||'';
      try{res=JSON.stringify(JSON.parse(res),null,2);}catch(e){}
      if(res.length>250) res=res.slice(0,250)+'...';
      codeHtml=`<div class="step-code"><b>Args:</b> ${esc(args)}\n<b>Result:</b> ${esc(res)}</div>`;
    }
    return `<div class="timeline-step${i===0?' active':''}" data-step="${i}">
      <div class="step-num">${step.icon}</div>
      <div class="step-body">
        <div class="step-tool">${step.tool}</div>
        <div class="step-desc">${step.desc}</div>
        ${codeHtml}
      </div>
    </div>`;
  }).join('');

  // Wire click interactions between flow nodes and timeline steps
  const flowNodes=flowBox.querySelectorAll('.flow-node');
  const timelineSteps=box.querySelectorAll('.timeline-step');
  function activateStep(idx){
    flowNodes.forEach((n,j)=>n.classList.toggle('active',j===idx));
    timelineSteps.forEach((s,j)=>{
      s.classList.toggle('active',j===idx);
      if(j===idx) s.scrollIntoView({behavior:'smooth',block:'nearest'});
    });
  }
  flowNodes.forEach(n=>n.addEventListener('click',()=>activateStep(parseInt(n.dataset.step))));
  timelineSteps.forEach(s=>s.addEventListener('click',()=>activateStep(parseInt(s.dataset.step))));
}

/* ---------- month labels for 366-day axis ---------- */
function dayAxis(){
  const MONTHS = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  const labels=[], starts={};
  for(let i=0;i<DATA.num_days;i++){
    const cur=new Date(2026,0,1+i);
    labels.push((cur.getMonth()+1)+'/'+cur.getDate());
    if(cur.getDate()===1 && i!==DATA.num_days-1) starts[i]=MONTHS[cur.getMonth()];
  }
  return {labels, starts};
}

/* ============ BALANCE CHART (animated frame-based, like embed.html) ============ */
let currentFrame=0, currentDay=0, balancePlaying=false, balanceTimer=null, balanceDayTimer=null;
/* false until the visitor asks for the tour, so the play button starts it from moment 1
   rather than resuming from the resting frame */
let tourStarted=false;
let balanceFocus=null;
const hidden={};

function fmtK(v){ return v>=1000?(v/1000).toFixed(v>=10000?0:1)+'k':v.toLocaleString(); }

function buildDots(){
  const el=document.getElementById('dots');
  el.innerHTML=FRAMES.map((frame,i)=>`<button type="button" class="fdot${i===0?' active':''}" data-i="${i}" aria-label="Go to moment ${i+1}: ${frame.title}"></button>`).join('');
  el.addEventListener('click', e=>{
    const d=e.target.closest('.fdot');
    if(d){ stopBalancePlay(); tourStarted=true; goToFrame(parseInt(d.dataset.i)); }
  });
}

function buildBalance(){
  const el=document.getElementById('balanceChart');
  if(charts.balance){try{charts.balance.dispose();}catch(e){}}
  const c=echarts.init(el,null,{renderer:'canvas'}); charts.balance=c;
  currentFrame=0; currentDay=0;
  buildDots();
  buildBalanceLegend();

  document.getElementById('btnPrev').onclick=()=>{
    stopBalancePlay(); tourStarted=true; goToFrame((currentFrame-1+FRAMES.length)%FRAMES.length);
  };
  document.getElementById('btnNext').onclick=()=>{
    stopBalancePlay(); tourStarted=true; goToFrame((currentFrame+1)%FRAMES.length);
  };
  document.getElementById('btnPlay').onclick=()=>{
    if(balancePlaying){ stopBalancePlay(); return; }
    if(!tourStarted){ tourStarted=true; goToFrame(0); }   // first press starts at moment 1
    startBalancePlay();
  };

  const vizCard=document.getElementById('balanceVizCard');
  // pause on hover so a reader can inspect, but never auto-resume on leave
  vizCard.addEventListener('mouseenter',()=>{ if(balancePlaying) stopBalancePlay(); });

  // Rest on the finished year instead of auto-playing: a visitor should meet the complete
  // curve, not a chart that moves under them. The 12-moment tour is opt-in via the play
  // button, which is also why the mouseleave auto-resume above is gone.
  showFullYear();
}

/* Three states for the tour trigger: at rest it invites you in, mid-tour it is a pause,
   and paused mid-tour it offers to resume rather than restart. */
function setPlayButton(state){
  const b=document.getElementById('btnPlay');
  const g=document.getElementById('playGlyph'), t=document.getElementById('playLabel');
  if(!b||!g||!t) return;
  b.classList.toggle('is-playing', state==='playing');
  if(state==='playing'){ g.innerHTML='&#10074;&#10074;'; t.textContent='Pause';
    b.title='Pause the tour'; }
  else if(state==='paused'){ g.innerHTML='&#9654;'; t.textContent='Resume';
    b.title='Resume the tour'; }
  else { g.innerHTML='&#9654;'; t.textContent='Play the year';
    b.title='Play the 12-moment tour'; }
}

/* The resting state: every model's full 365 days, no frame narration, no timer. */
function showFullYear(){
  stopBalancePlay();
  tourStarted=false;
  currentFrame=FRAMES.length-1;
  currentDay=DATA.num_days-1;
  updateBalanceChart(currentDay);
  document.getElementById('frameLabel').textContent='Full year';
  document.getElementById('frameTitle').textContent='All 365 days';
  document.getElementById('frameDesc').textContent=
    'Every model\u2019s complete year \u2014 hit \u25B6 Play the year to walk through the 12 moments that shaped it.';
  document.getElementById('progressFill').style.width='100%';
  document.querySelectorAll('#dots .fdot').forEach(d=>d.classList.remove('active'));
  const ev=document.getElementById('eventCard'); if(ev) ev.classList.remove('visible');
  setPlayButton('rest');
}

function updateBalanceChart(day){
  const c=charts.balance; if(!c) return;
  const ax=dayAxis(); const k=ink();

  const series=MODELS.map(m=>{
    const visibleCurve=m.balance_curve.slice(0, day+1);
    const isHero=m.hero;
    const lk=logoKey(m.id);
    const hasLogo=!!LOGO_DATA_URI[lk];
    return {
      name:m.name, type:'line', data:visibleCurve, showSymbol:false, smooth:0.3,
      lineStyle:{width:isHero?3:1.5, color:col(m.id), opacity:isHero?1:0.5},
      itemStyle:{color:col(m.id)}, z:isHero?10:1,
      endLabel:{
        show:true,
        formatter: hasLogo ? '{logo|}' : '{name|'+m.name+'}',
        rich: hasLogo ? {
          logo:{backgroundColor:{image:LOGO_DATA_URI[lk]}, width:20, height:20}
        } : {
          name:{fontSize:9, fontWeight:isHero?700:400, color:col(m.id)}
        },
        distance:4
      },
      areaStyle:isHero?{color:new echarts.graphic.LinearGradient(0,0,0,1,[
        {offset:0,color:col(m.id)+'22'},{offset:1,color:col(m.id)+'02'}
      ])}:undefined,
      /* At the resting frame 14 of the 18 finish under a quarter of the leader and bunch at
         the bottom of the axis, so their badges collide. shiftY was tried and is worse: it
         keeps all 18 by stacking them into a column that spills below the x-axis, detached
         from the lines it labels. Dropping the colliders instead leaves the well-separated
         leaders badged, and the legend underneath identifies every model anyway. */
      labelLayout:{hideOverlap:true},
    };
  });

  if(series.length>0){
    series[0].markLine={
      silent:true, symbol:'none', animation:false,
      data:[{xAxis:day, lineStyle:{color:DARK?'#555':'#bbb', type:'dashed', width:1}, label:{show:false}}],
    };
  }

  const markAreas=PROMO_BANDS.filter(b=>b.start<=day).map(b=>([
    {xAxis:b.start, itemStyle:{color:b.mult>=3?(DARK?'rgba(255,160,40,.12)':'rgba(255,140,0,.07)'):(DARK?'rgba(42,120,214,.10)':'rgba(42,120,214,.05)')}},
    {xAxis:Math.min(b.end, day)},
  ]));
  if(series.length>0 && markAreas.length>0){
    series[0].markArea={silent:true, data:markAreas};
  }

  c.setOption({
    animation:true, animationDuration:400,
    grid:{left:70, right:110, top:20, bottom:40},
    legend:{show:false, selected:Object.fromEntries(MODELS.map(m=>[m.name,!hidden[m.name]]))},
    xAxis:{type:'category', data:ax.labels, boundaryGap:false,
      axisLine:{lineStyle:{color:k.axis}}, axisTick:{show:false},
      axisLabel:{fontSize:10, color:k.muted, interval:(i)=>ax.starts[i]!==undefined,
        formatter:(v,i)=>ax.starts[i]||''}},
    yAxis:{type:'value', axisLine:{show:false},
      splitLine:{lineStyle:{color:k.grid, type:'dashed'}},
      axisLabel:{fontSize:10, color:k.muted, formatter:v=>fmtK(v)}},
    series:series,
    tooltip:{show:false},
  }, true);
}

function goToFrame(idx, skipChartJump){
  currentFrame=idx;
  const frame=FRAMES[idx];
  document.getElementById('frameLabel').textContent=`Day ${frame.day} · ${idx+1}/${FRAMES.length}`;
  document.getElementById('frameTitle').textContent=frame.title;
  document.getElementById('frameDesc').textContent=frame.desc;

  const dots=document.querySelectorAll('#dots .fdot');
  dots.forEach((d,i)=>d.classList.toggle('active', i===idx));

  if(!skipChartJump){
    currentDay=frame.day;
    document.getElementById('progressFill').style.width=`${(frame.day/365)*100}%`;
    updateBalanceChart(frame.day);
  }
  updateEventCard(frame);
}

function updateEventCard(frame){
  const card=document.getElementById('eventCard');
  const icon=FRAME_ICONS[frame.icon]||'📌';
  document.getElementById('evIcon').textContent=icon;
  document.getElementById('evTitle').textContent=frame.title;
  document.getElementById('evDetail').textContent=frame.desc;

  const link=document.getElementById('evLink');
  if(frame.link){
    link.href=frame.link;
    link.style.display='inline';
  } else {
    link.style.display='none';
  }

  card.classList.remove('visible');
  setTimeout(()=>{ card.classList.add('visible'); }, 50);
}

function updateDayDisplay(){
  const pct=(currentDay/365)*100;
  document.getElementById('progressFill').style.width=pct+'%';
  const frame=FRAMES[currentFrame];
  document.getElementById('frameLabel').textContent=`Day ${currentDay} · ${currentFrame+1}/${FRAMES.length}`;
}

function startBalancePlay(){
  balancePlaying=true;
  setPlayButton('playing');
  stopBalanceTimers();
  const frame=FRAMES[currentFrame];
  const targetDay=frame.day;
  goToFrame(currentFrame, true);
  if(currentDay<targetDay){
    balanceDayTimer=setInterval(()=>{
      currentDay+=2;
      if(currentDay>=targetDay){
        currentDay=targetDay;
        clearInterval(balanceDayTimer); balanceDayTimer=null;
        updateBalanceChart(currentDay);
        updateDayDisplay();
        balanceTimer=setTimeout(()=>{
          if(!balancePlaying) return;
          currentFrame=(currentFrame+1)%FRAMES.length;
          if(currentFrame===0) currentDay=0;
          startBalancePlay();
        }, 2500);
      } else {
        updateBalanceChart(currentDay);
        updateDayDisplay();
      }
    }, 60);
  } else {
    updateBalanceChart(currentDay);
    balanceTimer=setTimeout(()=>{
      if(!balancePlaying) return;
      currentFrame=(currentFrame+1)%FRAMES.length;
      if(currentFrame===0) currentDay=0;
      startBalancePlay();
    }, 2500);
  }
}

function stopBalanceTimers(){
  if(balanceTimer){clearTimeout(balanceTimer); balanceTimer=null;}
  if(balanceDayTimer){clearInterval(balanceDayTimer); balanceDayTimer=null;}
}

function stopBalancePlay(){
  balancePlaying=false;
  setPlayButton(tourStarted ? 'paused' : 'rest');
  stopBalanceTimers();
}

function setBalanceFocus(i){ if(i===balanceFocus)return;
  if(hidden[MODELS[i].name]) return;
  balanceFocus=i; const c=charts.balance;
  c.dispatchAction({type:'downplay'});
  c.dispatchAction({type:'highlight', seriesIndex:i});
}
function clearBalanceFocus(){ if(balanceFocus==null)return; balanceFocus=null;
  charts.balance.dispatchAction({type:'downplay'}); }

function buildBalanceLegend(){
  const box=document.getElementById('balanceLegend');
  box.innerHTML='';
  MODELS.forEach((m,i)=>{
    const b=document.createElement('button');
    b.className='lg'+(m.hero?' hero':'')+(hidden[m.name]?' off':'');
    b.innerHTML=logoSvg(m.id,14)+`<span class="dot" style="background:${col(m.id)}"></span>${m.name}`;
    b.onmouseenter=()=>{ if(!hidden[m.name]) setBalanceFocus(i); };
    b.onmouseleave=clearBalanceFocus;
    b.onclick=()=>{ hidden[m.name]=!hidden[m.name];
      charts.balance.dispatchAction({type:hidden[m.name]?'legendUnSelect':'legendSelect', name:m.name});
      b.classList.toggle('off', !!hidden[m.name]); clearBalanceFocus(); };
    box.appendChild(b);
  });
}
function buildBalanceTable(){
  const rows=[...MODELS].sort((a,b)=>(b.final_balance||0)-(a.final_balance||0)).map(m=>{
    const s=m.final_balance_summary||{};
    const pTag=m.partial?' <small style="opacity:.6">(day '+m.partial_day+')</small>':'';
    return `<tr class="${m.hero?'hero':''}"><td>${logoSvg(m.id,16)}<span class="mdot" style="background:${col(m.id)}"></span>${m.name}${pTag}</td>
      <td>${yuan(m.final_balance)}${pTag?'*':''}</td><td>±${s.std!=null?yuan(s.std):'—'}</td>
      <td>${m.bankrupt_count||0}/5</td></tr>`; }).join('');
  document.getElementById('balanceTable').innerHTML=
    `<div class="tb-wrap"><table class="tb"><thead><tr><th>Model</th><th>Final Balance (avg)</th><th>Std Dev</th><th>Bankrupt Runs</th></tr></thead><tbody>${rows}</tbody></table></div>`;
}

/* ============ NEGOTIATION IN ACTION (side-by-side comparison) ============ */
let negoCompareLeft=null, negoCompareRight=null;
function buildNegoCompare(){
  const heroIdx=MODELS.findIndex(m=>m.hero);
  const otherIdx=MODELS.findIndex(m=>m.id==='gpt56sol')||MODELS.findIndex(m=>m.id==='gpt55');
  negoCompareLeft=heroIdx>=0?heroIdx:0;
  negoCompareRight=otherIdx>=0?otherIdx:(heroIdx>=0?(heroIdx===0?1:0):1);

  function renderTabs(containerId, side){
    const box=document.getElementById(containerId); box.innerHTML='';
    const lbl=document.createElement('span');
    lbl.style.cssText='font-size:12px;color:var(--muted);font-weight:600;margin-right:4px';
    lbl.textContent=side==='left'?'Left:':'Right:';
    box.appendChild(lbl);
    MODELS.forEach((m,i)=>{
      const b=document.createElement('button');
      b.className='model-tab'+((side==='left'?negoCompareLeft:negoCompareRight)===i?' active':'');
      b.innerHTML=logoSvg(m.id,14)+`<span class="mdot" style="background:${col(m.id)};display:inline-block;width:8px;height:8px;border-radius:2px;margin-right:4px;vertical-align:middle"></span>${m.name}`;
      b.onclick=()=>{
        if(side==='left') negoCompareLeft=i; else negoCompareRight=i;
        renderTabs('negoLeftTabs','left');
        renderTabs('negoRightTabs','right');
        renderPanels();
      };
      box.appendChild(b);
    });
  }

  function renderPanels(){
    const mL=MODELS[negoCompareLeft], mR=MODELS[negoCompareRight];
    const left=document.getElementById('negoLeft');
    const right=document.getElementById('negoRight');
    left.innerHTML=`<h3>${logoSvg(mL.id,18)}<span class="mdot" style="background:${col(mL.id)}"></span>${mL.name}</h3>`
      +(mL.chatbox_example?renderChat(mL.chatbox_example):'<p class="note">No transcript available.</p>');
    right.innerHTML=`<h3>${logoSvg(mR.id,18)}<span class="mdot" style="background:${col(mR.id)}"></span>${mR.name}</h3>`
      +(mR.chatbox_example?renderChat(mR.chatbox_example):'<p class="note">No transcript available.</p>');

    const insight=document.getElementById('negoCompareInsight');
    insight.innerHTML='<b>Key differences:</b> Compare how each model opens the conversation, '
      +'whether it requests catalogs by product ID or by name, the aggressiveness of initial offers, '
      +'and how quickly it commits to purchase. Some models negotiate multiple SKUs in parallel while '
      +'others take a sequential approach.';
  }

  renderTabs('negoLeftTabs','left');
  renderTabs('negoRightTabs','right');
  renderPanels();
}

/* ============ generic multi-series line with nearest hover ============ */
function multiLine(elId, seriesData, xData, yName, yFmt){
  const el=document.getElementById(elId); const c=echarts.init(el); charts[elId]=c;
  const k=ink();
  const series=MODELS.map(m=>({
    name:m.name, type:'line', data:seriesData(m), connectNulls:true,
    showSymbol:false, lineStyle:{width:m.hero?3.2:1.6,color:col(m.id)}, itemStyle:{color:col(m.id)},
    emphasis:{focus:'series',lineStyle:{width:m.hero?4:3}}, blur:{lineStyle:{opacity:.1}}, z:m.hero?10:2
  }));
  c.setOption({
    grid:baseGrid(), legend:{show:false},
    xAxis:{type:'category',data:xData,boundaryGap:false,axisLine:{lineStyle:{color:k.axis}},
      axisTick:{show:false},axisLabel:{color:k.muted}},
    yAxis:{type:'value',name:yName||'',nameTextStyle:{color:k.muted,align:'left'},
      axisLabel:{color:k.muted,formatter:yFmt},splitLine:{lineStyle:{color:k.grid}},axisLine:{show:false}},
    tooltip:{trigger:'axis',...tooltipStyle(),confine:true,
      axisPointer:{type:'line',lineStyle:{color:k.muted,type:'dashed'}}},
    series
  });
  const zr=c.getZr();
  zr.on('mousemove',ev=>{ const pt=[ev.offsetX,ev.offsetY];
    if(!c.containPixel({gridIndex:0},pt)){c.dispatchAction({type:'downplay'});return;}
    const xy=c.convertFromPixel({gridIndex:0},pt);
    const idx=Math.round(xy[0]); let best=-1,bd=Infinity;
    MODELS.forEach((m,i)=>{const d=seriesData(m)[idx]; if(d==null)return;
      const dist=Math.abs(d-xy[1]); if(dist<bd){bd=dist;best=i;}});
    if(best>=0&&best!==c._foc){c._foc=best;c.dispatchAction({type:'downplay'});
      c.dispatchAction({type:'highlight',seriesIndex:best});}
  });
  zr.on('globalout',()=>{c.dispatchAction({type:'downplay'});c._foc=-1;});
  return c;
}

/* ============ NEGO section ============ */
function buildNego(){
  const k=ink();
  const fams=DATA.radar_families;
  const rc=echarts.init(document.getElementById('radarChart')); charts.radar=rc;
  const allv=MODELS.flatMap(m=>fams.map(f=>m.radar[f])).filter(v=>v!=null);
  const maxv=Math.max(...allv), minv=Math.max(0,Math.floor(Math.min(...allv)*10)/10-0.05);
  /* All 18 polygons at once are an unreadable tangle, so only a contrasting handful start
     enabled and the legend carries the rest. The default set is picked from the paper table:
     the hero, the best and weakest negotiators by CSE+, and the top earner. */
  const byCse=[...PAPER].sort((a,b)=>b.cse-a.cse);
  const defaultIds=new Set([
    (MODELS.find(m=>m.hero)||MODELS[0]).id,
    byCse[0].id,
    byCse[byCse.length-1].id,
    [...PAPER].sort((a,b)=>b.assets-a.assets)[0].id
  ]);
  const onByDefault=m=>defaultIds.has(m.id);
  rc.setOption({
    tooltip:{...tooltipStyle(),confine:true},
    /* the scroll legend pages horizontally, so the enabled models are listed first and
       land on page 1 instead of being stranded three pages in */
    legend:{data:[...MODELS].sort((a,b)=>(onByDefault(b)?1:0)-(onByDefault(a)?1:0)).map(m=>m.name),
      type:'scroll', bottom:0, itemGap:9,
      itemWidth:12, itemHeight:8, textStyle:{color:k.ink2,fontSize:10.5},
      /* the card is half-width, so the effort suffix is dropped from the label only;
         the series name it toggles is still the full paper label */
      formatter:v=>v.replace(' (max)',''),
      pageTextStyle:{color:k.muted}, pageIconSize:10,
      selected:Object.fromEntries(MODELS.map(m=>[m.name, onByDefault(m)]))},
    radar:{indicator:fams.map(f=>({name:f,max:Math.min(1,Math.ceil(maxv*10)/10+0.02),min:minv})),
      /* radius is a share of min(width,height)/2, so in a full-width card the 480px height
         is what bounds it -- 58% of that left the polygon floating in white space */
      radius:'74%', center:['50%','45%'], axisName:{color:k.ink2,fontSize:12},
      splitLine:{lineStyle:{color:k.grid}}, splitArea:{show:false},
      axisLine:{lineStyle:{color:k.grid}}},
    series:[{type:'radar', symbolSize:4, data:MODELS.map(m=>({name:m.name, value:fams.map(f=>m.radar[f]),
      lineStyle:{width:m.hero?3:1.8,color:col(m.id),opacity:m.hero?1:0.8},
      itemStyle:{color:col(m.id)},
      areaStyle:m.hero?{color:col(m.id),opacity:.15}:undefined,
      emphasis:{focus:'self',lineStyle:{width:3,opacity:1},areaStyle:{opacity:.1}},
      z:m.hero?10:2}))}]
  });
  const hero = MODELS.find(m => m.hero) || MODELS[0];

  // Deal anatomy — one negotiation cycle ending in a clear DEAL
  const dex = DATA.deal_example;
  /* Deal Anatomy is the paper's own fig_3_5_anchoring now, so #dealExample is gone from the
     markup. This block is guarded rather than deleted, so re-adding the element brings the
     interactive version back. */
  const dEl = document.getElementById('dealExample');
  if (dEl && dex && dex.steps && dex.steps.length) {
    const dc = echarts.init(dEl); charts.dealEx = dc;
    const ref = dex.ref, floor = dex.floor;
    const steps = dex.steps;
    const n = steps.length;
    const prices = steps.map(s => s.price);
    const finalPrice = prices[n - 1];
    const firstCounter = (steps.find(s => s.who === 'supplier' && s.act === 'counter') || {}).price;
    const dropFromFirst = firstCounter ? ((firstCounter - finalPrice) / firstCounter * 100).toFixed(0) : '—';
    const discount = ((ref - finalPrice) / ref * 100).toFixed(0);

    // Per-point style: final accept = gold star, agent = blue square, supplier = red circle
    const pointColors = steps.map((s, i) => {
      if (i === n - 1 && s.act === 'accept') return '#c76a1a';
      return s.who === 'agent' ? '#2a78d6' : '#d03b3b';
    });
    const pointSymbols = steps.map((s, i) => {
      if (i === n - 1 && s.act === 'accept') return 'diamond';
      return s.who === 'agent' ? 'rect' : 'circle';
    });
    const pointSizes = steps.map((s, i) => (i === n - 1 && s.act === 'accept') ? 20 : 11);

    const yMin = Math.floor(Math.min(...prices, floor) * 0.90);
    const yMax = Math.ceil(Math.max(...prices, ref) * 1.05);

    dc.setOption({
      grid: { left: 8, right: 12, top: 42, bottom: 30, containLabel: true },
      title: {
        text: dex.supplier + ' · ' + n + ' turns · Deal at ¥' + finalPrice.toFixed(0) + ' (−' + discount + '% off ref)',
        subtext: 'Agent drove supplier from ¥' + (firstCounter ? firstCounter.toFixed(0) : '?') + ' → ¥' + finalPrice.toFixed(0) + ', −' + dropFromFirst + '% off its first counter',
        left: 'center', top: 2,
        textStyle: { fontSize: 12, color: k.ink, fontWeight: 700 },
        subtextStyle: { fontSize: 10.5, color: k.ink2, fontWeight: 500 }
      },
      xAxis: {
        type: 'category', data: steps.map((s, i) => 'T' + (i + 1)), boundaryGap: false,
        axisLabel: { color: k.muted, fontSize: 9.5 },
        axisLine: { lineStyle: { color: k.grid } }, axisTick: { show: false }
      },
      yAxis: {
        type: 'value', min: yMin, max: yMax,
        /* yMax is derived from the reference price and rarely lands on a tick, so its
           label would print on top of the last gridline label */
        axisLabel: { color: k.muted, fontSize: 9.5, formatter: v => '¥' + v, showMaxLabel: false },
        splitLine: { lineStyle: { color: k.grid } }, axisLine: { show: false }
      },
      tooltip: {
        ...tooltipStyle(), confine: true, trigger: 'axis',
        formatter: params => {
          const p = params[0]; if (!p) return '';
          const i = p.dataIndex, s = steps[i];
          const who = s.who === 'agent' ? 'Agent' : 'Supplier';
          const act = s.act.charAt(0).toUpperCase() + s.act.slice(1);
          const isDeal = (i === n - 1 && s.act === 'accept');
          return 'Turn ' + (i + 1) + '<br><b>' + who + '</b>: ' + act + ' ¥' + s.price.toFixed(1) + (isDeal ? '<br><b style="color:#c76a1a">✓ DEAL</b>' : '');
        }
      },
      legend: {
        bottom: 0, textStyle: { color: k.ink2, fontSize: 10 }, itemWidth: 14, itemHeight: 8,
        data: [
          { name: 'Agent offer', icon: 'rect' },
          { name: 'Supplier counter', icon: 'circle' },
          { name: 'DEAL', icon: 'diamond' }
        ]
      },
      series: [{
        name: 'Price', type: 'line', data: prices,
        lineStyle: { color: k.muted, width: 1.8, opacity: 0.5 },
        z: 5,
        itemStyle: {
          color: p => pointColors[p.dataIndex],
          borderColor: p => (p.dataIndex === n - 1 ? '#8a4a10' : 'transparent'),
          borderWidth: p => (p.dataIndex === n - 1 ? 2 : 0)
        },
        symbol: (v, p) => pointSymbols[p.dataIndex],
        symbolSize: (v, p) => pointSizes[p.dataIndex],
        markPoint: {
          symbol: 'pin', symbolSize: 44, silent: true,
          data: [{
            coord: [n - 1, finalPrice],
            value: '✓',
            itemStyle: { color: '#c76a1a', opacity: 0.85 },
            label: { color: '#fff', fontSize: 12, fontWeight: 700, offset: [0, -2] }
          }]
        }
      },
      { name: 'Agent offer', type: 'line', data: [], itemStyle: { color: '#2a78d6' }, symbol: 'rect' },
      { name: 'Supplier counter', type: 'line', data: [], itemStyle: { color: '#d03b3b' }, symbol: 'circle' },
      { name: 'DEAL', type: 'line', data: [], itemStyle: { color: '#c76a1a' }, symbol: 'diamond' },
      { type: 'line', data: [], markLine: {
          silent: true, symbol: 'none',
          lineStyle: { type: 'dashed', width: 1 }, data: [
            { yAxis: ref, lineStyle: { color: '#2ea63c', opacity: 0.5 },
              label: { show: true, position: 'insideEndTop', formatter: 'Ref ¥' + ref.toFixed(0), fontSize: 9.5, color: '#2ea63c', fontWeight: 600 } },
            { yAxis: floor, lineStyle: { color: '#eb9b34', opacity: 0.5 },
              label: { show: true, position: 'insideEndBottom', formatter: 'Floor ¥' + floor.toFixed(0), fontSize: 9.5, color: '#eb9b34', fontWeight: 600 } }
          ] } }]
    });
  }

  const traces = hero.nego_traces || [];
  const grid = document.getElementById('negoTraceGrid');
  grid.innerHTML = '';
  const heroColor = col(hero.id);
  traces.forEach((sku, si) => {
    const div = document.createElement('div');
    div.style.cssText = 'height:280px;min-width:0;';
    grid.appendChild(div);
    const ch = echarts.init(div);
    charts['negoTrace' + si] = ch;

    const ref = sku.ref || 1;
    const floor = sku.floor || 0;
    const nRounds = sku.traces.length;

    const dealPrices = [];
    const runMin = [];
    let best = Infinity;
    sku.traces.forEach((tr, ti) => {
      if (tr.deal != null) {
        dealPrices.push([ti + 1, tr.deal]);
        if (tr.deal < best) best = tr.deal;
        runMin.push([ti + 1, best]);
      }
    });

    const firstDeal = dealPrices.length > 0 ? dealPrices[0][1] : null;
    const bestDeal = best < Infinity ? best : null;
    const dropPct = firstDeal && bestDeal ? ((firstDeal - bestDeal) / firstDeal * 100).toFixed(0) : 0;

    const series = [];

    // Comparison model (flat/stuck) — faded gray line behind hero
    const comp = sku.comparison;
    if (comp && comp.prices && comp.prices.length) {
      const compPrices = comp.prices.map((p, i) => [i + 1, p]);
      const compMin = [];
      let cBest = Infinity;
      comp.prices.forEach((p, i) => { if (p < cBest) cBest = p; compMin.push([i + 1, cBest]); });
      series.push({
        name: comp.model, type: 'line', data: compPrices,
        symbol: 'diamond', symbolSize: 5,
        lineStyle: { color: '#999', width: 1.5, type: 'dashed' },
        itemStyle: { color: '#999', opacity: 0.6 }, z: 2
      });
    }

    series.push({
      name: hero.name, type: 'line', data: dealPrices,
      symbol: 'circle', symbolSize: 7,
      lineStyle: { color: heroColor, width: 2.5 },
      itemStyle: { color: heroColor }, z: 5
    });

    if (runMin.length > 1) {
      const stepData = [];
      for (let i = 0; i < runMin.length; i++) {
        stepData.push([runMin[i][0], runMin[i][1]]);
        if (i + 1 < runMin.length) stepData.push([runMin[i + 1][0], runMin[i][1]]);
      }
      series.push({
        name: 'Best so far', type: 'line', data: stepData,
        showSymbol: false,
        lineStyle: { color: '#c76a1a', width: 2.2, type: 'solid' },
        areaStyle: { color: '#c76a1a', opacity: 0.06 },
        z: 3, silent: true
      });
    }

    series.push({
      type: 'line', data: [], markLine: {
        silent: true, symbol: 'none',
        lineStyle: { type: 'dashed', width: 1 },
        data: [
          { yAxis: ref, lineStyle: { color: '#2ea63c', opacity: 0.45 },
            label: { show: true, position: 'insideEndTop', formatter: 'Ref ¥' + ref.toFixed(0), fontSize: 9, color: '#2ea63c' } },
          { yAxis: floor, lineStyle: { color: '#eb9b34', opacity: 0.45 },
            label: { show: true, position: 'insideEndBottom', formatter: 'Floor ¥' + floor.toFixed(0), fontSize: 9, color: '#eb9b34' } }
        ]
      }
    });

    const supName = sku.supplier ? sku.supplier.split(' ').slice(0, 2).join(' ') : '';
    const compLen = comp && comp.prices ? comp.prices.length : 0;
    const xMax = Math.max(nRounds, compLen) + 0.5;
    ch.setOption({
      grid: { left: 8, right: 12, top: 34, bottom: 20, containLabel: true },
      title: { text: supName + ' · −' + dropPct + '%',
        left: 'center', top: 2, textStyle: { fontSize: 11.5, color: k.ink2, fontWeight: 600 } },
      xAxis: { type: 'value', min: 0.5, max: xMax,
        axisLabel: { color: k.muted, fontSize: 9, formatter: v => 'R' + Math.round(v) },
        splitLine: { show: false }, axisLine: { lineStyle: { color: k.grid } },
        axisTick: { show: false }, interval: Math.max(1, Math.floor(xMax / 10)) },
      yAxis: { type: 'value',
        axisLabel: { color: k.muted, fontSize: 9.5, formatter: v => '¥' + v.toFixed(0) },
        splitLine: { lineStyle: { color: k.grid } }, axisLine: { show: false } },
      tooltip: { ...tooltipStyle(), confine: true, trigger: 'axis',
        formatter: params => {
          const ri = Math.round(params[0]?.data?.[0] || 1);
          return 'Round ' + ri + '<br>' + params.filter(p => p.data && p.data[1] != null).map(p =>
            p.marker + ' ' + p.seriesName + ': ¥' + p.data[1].toFixed(2)).join('<br>');
        }
      },
      legend: { bottom: 0, textStyle: { color: k.muted, fontSize: 9 }, itemWidth: 12, itemHeight: 8 },
      series
    });
  });
}

