function sortedBy(fn, asc=true){ return [...MODELS].sort((a,b)=>asc?fn(a)-fn(b):fn(b)-fn(a)); }
function hbar(elId, arr, valFn, fmt, colorFn){
  const el=document.getElementById(elId); const c=echarts.init(el); charts[elId]=c; const k=ink();
  c.setOption({
    grid:{...baseGrid(), left:8, right:54},   // room for the end-of-bar labels
    xAxis:{type:'value',axisLabel:{color:k.muted,formatter:fmt},splitLine:{lineStyle:{color:k.grid}},axisLine:{show:false}},
    yAxis:{type:'category',data:arr.map(m=>m.name),inverse:true,axisLine:{lineStyle:{color:k.axis}},
      axisTick:{show:false},axisLabel:{color:k.ink2,fontWeight:'bold',
        formatter:v=>{const m=arr.find(x=>x.name===v);return (m&&m.hero)?('{h|'+v+'}'):v;},
        rich:{h:{color:k.ink,fontWeight:'bold'}}}},
    tooltip:{trigger:'item',...tooltipStyle(),confine:true,formatter:p=>`${p.name}<br>${fmt(p.value)}`},
    /* Squared ends, a hairline white gap between bars and a quiet value label at the end:
       the paper's model_bars does the same (edgecolor white, height 0.74, small annotation).
       The rounded pill ends this had made short bars read as UI chrome rather than data,
       and without a label the colour was carrying nothing the row label did not. */
    series:[{type:'bar', barWidth:'74%',
      data:arr.map(m=>({value:valFn(m),
        itemStyle:{color:(colorFn||col)(m.id), borderColor:k.surface, borderWidth:0.8}})),
      label:{show:true, position:'right', color:k.ink2, fontSize:10.5,
             formatter:p=>fmt(p.value)}}]
  });
  return c;
}
