    xAxis:{type:'value',axisLabel:{color:k.muted},splitLine:{lineStyle:{color:k.grid}},axisLine:{show:false}},
    yAxis:{type:'category',data:arr.map(m=>m.name),inverse:true,axisLine:{lineStyle:{color:k.axis}},
      axisTick:{show:false},axisLabel:heroLabel(k)},
