/* ============ Capability profile radar (paper Figure 2) ============ */
/* Seven axes: the primary score plus the six dimensions. `flip` marks the axes the
   paper sign-flips so that outward is better on every one of them. Normalisation is
   min-max over all 18 model means, so 1 is the best of the eighteen and 0 the worst. */
/* Listed counter-clockwise, because ECharts places indicator[0] at the top and walks
   counter-clockwise -- which renders as the paper's clockwise-from-the-top order:
   Profit, Negotiation, Fraud avoidance, Solvency, Efficiency, Execution, Learning. */
const PROFILE_AXES = [
  {key:'assets', name:'Profit',          flip:false},
  {key:'ar',     name:'Learning',        flip:true},
  {key:'ctrl',   name:'Execution',       flip:true},
  {key:'ypc',    name:'Efficiency',      flip:false},
  {key:'dd',     name:'Solvency',        flip:true},
  {key:'bad',    name:'Fraud avoidance', flip:true},
  {key:'cse',    name:'Negotiation',     flip:false}
];

function normAxis(ax){
  const vals = PAPER.map(r=>r[ax.key]);
  const lo = Math.min(...vals), hi = Math.max(...vals);
  return v => {
    if(hi===lo) return 0.5;
    const t = (v-lo)/(hi-lo);
    return ax.flip ? 1-t : t;
  };
}
function median(a){ const v=[...a].sort((x,y)=>x-y), n=v.length;
  return n%2 ? v[(n-1)/2] : (v[n/2-1]+v[n/2])/2; }

/* strongest model of each vendor family by mean total assets, which is how the paper
   picks the seven the figure draws */
function familyReps(){
  const best={};
  PAPER.forEach(r=>{ if(!best[r.family] || r.assets>best[r.family].assets) best[r.family]=r; });
  return Object.values(best).sort((a,b)=>b.assets-a.assets);
}

function buildProfile(){
  const k=ink();
  const norms = PROFILE_AXES.map(normAxis);
  const reps = familyReps();
  const medianVec = PROFILE_AXES.map((ax,i)=>+median(PAPER.map(r=>norms[i](r[ax.key]))).toFixed(3));

  const series = reps.map(r=>({
    name: pname(r.id),
    value: PROFILE_AXES.map((ax,i)=>+norms[i](r[ax.key]).toFixed(3)),
    lineStyle:{width:2.2, color:col(r.id)},
    itemStyle:{color:col(r.id)},
    areaStyle:{color:col(r.id), opacity:0.06},
    symbolSize:5
  }));
  series.push({
    name:'18-model median',
    value: medianVec,
    lineStyle:{width:1.6, type:'dashed', color:k.muted},
    itemStyle:{color:k.muted}, symbolSize:0, areaStyle:{opacity:0}
  });

  const el=document.getElementById('profileChart');
  if(!el) return;
  const ch=echarts.init(el); charts.profile=ch;
  ch.setOption({
    tooltip:{trigger:'item',...tooltipStyle(),confine:true,
      formatter:p=>{
        const rows=PROFILE_AXES.map((ax,i)=>
          ax.name+': '+(p.value[i]*100).toFixed(0)+'<span style="opacity:.6"> / 100</span>').join('<br>');
        return '<b>'+p.name+'</b><br>'+rows;
      }},
    legend:{data:series.map(x=>x.name), bottom:0, itemGap:14, itemWidth:14, itemHeight:9,
      textStyle:{color:k.ink2, fontSize:11.5}, type:'scroll'},
    radar:{
      indicator: PROFILE_AXES.map(a=>({name:a.name, max:1, min:0})),
      center:['50%','46%'], radius:'62%', splitNumber:4,
      axisName:{color:k.ink2, fontSize:12, fontWeight:600},
      splitLine:{lineStyle:{color:k.grid}},
      splitArea:{areaStyle:{color:['transparent']}},
      axisLine:{lineStyle:{color:k.grid}}
    },
    series:[{type:'radar', emphasis:{focus:'series', areaStyle:{opacity:0.16}}, data:series}]
  });

  /* count how many of the drawn seven sit below the 18-model median somewhere -- the
     paper's "six of the seven" line, recomputed rather than hard-coded */
  const below = reps.filter(r =>
    PROFILE_AXES.some((ax,i)=> norms[i](r[ax.key]) < medianVec[i]));
  const clean = reps.filter(r=>!below.includes(r)).map(r=>pname(r.id));
  const note=document.getElementById('profileNote');
  if(note) note.innerHTML =
    '<b>'+below.length+' of the '+reps.length+'</b> models drawn here fall below the 18-model median on at least one axis'
    + (clean.length ? '. The only exception is <b>'+clean.join(', ')+'</b>, which sits at or above the median on all seven.'
                    : '.');
}

/* ============ Learning over the horizon (paper Table D6) ============ */
function anchorColour(r){
  if(r.z >  ANCHOR_SIG) return DARK ? '#19b219' : '#0ca30c';   /* beat its own shuffle */
  if(r.z < -ANCHOR_SIG) return DARK ? '#e66767' : '#d03b3b';   /* lost to it */
  return DARK ? '#6e6c66' : '#a9a7a0';                          /* not significant */
}

function buildLearning(){
  const k=ink();
  const arr=[...PAPER].sort((a,b)=>a.ar-b.ar);          /* lower AnchorRatio first */
  const el=document.getElementById('anchorChart');
  if(el){
    const ch=echarts.init(el); charts.anchor=ch;
    ch.setOption({
      grid:{...baseGrid(), left:8, right:56},
      /* values are plotted as AnchorRatio - 1, so zero is the neutral point and a bar
         pointing left means the agent beat a reshuffle of its own quotes. Axis labels
         and bar labels are mapped back to the ratio the paper prints. */
      xAxis:{type:'value', min:-0.5, max:0.9, interval:0.1,
        axisLabel:{color:k.muted, formatter:v=>(1+v).toFixed(2)},
        splitLine:{lineStyle:{color:k.grid}}, axisLine:{show:false}},
      yAxis:{type:'category', data:arr.map(r=>pname(r.id)), inverse:true,
        axisLine:{lineStyle:{color:k.axis}}, axisTick:{show:false}, axisLabel:heroLabel(k)},
      tooltip:{trigger:'item',...tooltipStyle(),confine:true,
        formatter:p=>{const r=arr[p.dataIndex];
          const verdict = r.z> ANCHOR_SIG ? 'beats its own shuffled ordering'
                        : r.z<-ANCHOR_SIG ? 'loses to its own shuffled ordering'
                        : 'indistinguishable from its own shuffled ordering';
          return '<b>'+pname(r.id)+'</b><br>AnchorRatio '+r.ar.toFixed(3)
               + '<br>z = '+(r.z>0?'+':'')+r.z.toFixed(2)+' &mdash; '+verdict
               + '<br><span style="opacity:.7">'+r.reorders+' re-orders</span>';}},
      series:[{
        type:'bar', barWidth:'74%',
        data:arr.map(r=>({value:+(r.ar-1).toFixed(3),
          itemStyle:{color:anchorColour(r), borderColor:k.surface, borderWidth:0.8},
          /* label position has to be set per item: ECharts 5 takes a string here, not a
             callback, and a callback silently lands every label on the wrong side */
          label:{position: r.ar>=1 ? 'right' : 'left'}})),
        label:{show:true, color:k.ink2, fontSize:11,
          formatter:p=>(1+p.value).toFixed(2)},
        markLine:{silent:true, symbol:'none', precision:2,
          lineStyle:{color:k.ink2, type:'dashed', width:1.4},
          data:[{xAxis:0}],
          label:{show:true, formatter:'1.0', rotate:0, position:'start',
            color:k.ink2, fontSize:11, fontWeight:600}}
      }]
    });
  }

  /* headline counts, recomputed from the paper table rather than written out */
  const better = PAPER.filter(r=>r.z >  ANCHOR_SIG);
  const worse  = PAPER.filter(r=>r.z < -ANCHOR_SIG);
  const above1 = PAPER.filter(r=>r.ar > 1);
  const reorders = PAPER.reduce((a,r)=>a+r.reorders,0);
  const cards=[
    {num:worse.length+' / '+PAPER.length, lab:'Anchored high', hint:'significantly worse than reshuffling their own quotes'},
    {num:better.length+' / '+PAPER.length, lab:'Actually learned', hint:better.map(r=>pname(r.id)).join(', '), accent:true},
    {num:above1.length+' / '+PAPER.length, lab:'AnchorRatio above 1.0', hint:'paid more than a random ordering would'},
    {num:reorders.toLocaleString('en-US'), lab:'Re-orders scored', hint:'over 2,230 repeat (supplier, SKU) pairs'}
  ];
  const st=document.getElementById('learningStats');
  if(st) st.innerHTML = cards.map(c=>
    `<div class="stat ${c.accent?'accent':''}"><div class="num">${c.num}</div>
     <div class="lab">${c.lab}</div><div class="hint">${c.hint}</div></div>`).join('');
}

/* ============ IntersectionObserver lazy init ============ */
const sectionBuilders = {
  profile: buildProfile,
  learning: buildLearning,
  daylife: buildDayInLife,
  nego: buildNego,
  'nego-compare': buildNegoCompare,
  fraud: buildFraud,
  tools: buildTools,
  terms: buildTerms,
  returns: buildReturns,
  finance: buildFinance
};

function setupSectionObservers(){
  const lazyObserver = new IntersectionObserver((entries)=>{
    entries.forEach(entry=>{
      if(entry.isIntersecting){
        const id = entry.target.id;
        if(!initialized[id] && sectionBuilders[id]){
          try{ sectionBuilders[id](); }catch(e){ console.error('build failed:',id,e); }
          initialized[id]=true;
        }
      }
    });
  }, {rootMargin:'200px'});

  Object.keys(sectionBuilders).forEach(id=>{
    const el = document.getElementById(id);
    if(el) lazyObserver.observe(el);
  });

  const navLinks = document.querySelectorAll('#topnav a[data-section]');
  const navObserver = new IntersectionObserver((entries)=>{
    entries.forEach(entry=>{
      if(entry.isIntersecting){
        const id = entry.target.id;
        navLinks.forEach(a=>a.classList.toggle('active', a.dataset.section===id));
      }
    });
  }, {rootMargin:'-48px 0px -60% 0px'});

  document.querySelectorAll('.eval-section, .hero, .methodology').forEach(sec=>{
    navObserver.observe(sec);
  });

  /* Scroll-reveal animation observer */
  const revealObserver = new IntersectionObserver((entries)=>{
    entries.forEach(entry=>{
      if(entry.isIntersecting){
        entry.target.classList.add('visible');
      }
    });
  }, {rootMargin:'0px 0px -60px 0px', threshold:0.05});
  document.querySelectorAll('.reveal, .reveal-left, .reveal-stagger').forEach(el=>{
    revealObserver.observe(el);
  });
}

/* table toggle */
document.getElementById('tableToggle').onclick=e=>{e.preventDefault();
  const t=document.getElementById('balanceTable'); const show=t.style.display==='none';
  if(show&&!t.innerHTML) buildBalanceTable(); t.style.display=show?'block':'none';};

/* theme change -> rebuild everything */
function reTheme(){ DARK=mq.matches;
  stopBalanceTimers();
  Object.values(charts).forEach(c=>{try{c.dispose();}catch(e){}});
  for(const k in charts) delete charts[k];
  for(const k in initialized) delete initialized[k];
  balanceFocus=null;
  buildBalance();
  const tbl=document.getElementById('balanceTable');
  if(tbl && tbl.style.display!=='none' && tbl.innerHTML) buildBalanceTable();
  Object.keys(sectionBuilders).forEach(id=>{
    const el = document.getElementById(id);
    if(el && isElementInViewport(el)){
      try{ sectionBuilders[id](); }catch(e){ console.error('rebuild failed:',id,e); }
      initialized[id]=true;
    }
  });
  setTimeout(()=>Object.values(charts).forEach(c=>c&&c.resize()),30);
}

function isElementInViewport(el){
  const rect = el.getBoundingClientRect();
  return rect.top < window.innerHeight && rect.bottom > 0;
}

mq.addEventListener('change',reTheme);
window.addEventListener('resize',()=>{clearTimeout(window._rz);
  window._rz=setTimeout(()=>Object.values(charts).forEach(c=>c&&c.resize()),120);});

/* boot */
function boot(d){
  DATA=d; MODELS=d.models;
  const status=document.getElementById('interactiveStatus');
  if(status) status.remove();
  buildHeadline(); buildStats(); buildBalance();

  /* A direct fragment link can otherwise land at a stale offset: lazy sections above
     the target expand only after the browser has already performed its anchor jump. */
  const hashTarget=location.hash && document.getElementById(decodeURIComponent(location.hash.slice(1)));
  if(hashTarget){
    Object.entries(sectionBuilders).forEach(([id,builder])=>{
      try{ builder(); initialized[id]=true; }
      catch(e){ console.error('deep-link build failed:',id,e); }
    });
  }
  setupSectionObservers();
  if(hashTarget){
    requestAnimationFrame(()=>requestAnimationFrame(()=>{
      hashTarget.scrollIntoView({block:'start'});
      Object.values(charts).forEach(c=>c&&c.resize());
    }));
  }
}
const _inline=document.getElementById('showcase-data');
if(_inline){ try{ boot(JSON.parse(_inline.textContent)); }catch(e){ console.error(e); } }
else fetch('showcase_data.json').then(r=>r.json()).then(boot).catch(err=>{
  const status=document.getElementById('interactiveStatus');
  if(status) status.textContent='Interactive charts could not load. Please refresh the page.';
  document.getElementById('main-content').insertAdjacentHTML('beforeend',
    '<p style="color:#d03b3b">Failed to load data: '+err+' (open via HTTP server, not file://)</p>');
});
